<script setup lang="ts">
import { bangkok, type Page } from '~/utils/types'
const {admin}=useSession();const api=useApi()
type Row=Record<string,string|number|null>
interface Summary {workflow:{pending:number;retry_wait:number;dead_letter:number;oldest_pending_age_seconds:number};mail:{pending:number;processing:number;retry_wait:number;failed:number;oldest_pending_age_seconds:number};open_exceptions:number;waiting_tasks:number;oldest_waiting_age_seconds:number;reconciliation_open:number;alerts:{code:string;count:number}[]}
interface Engine {document_id:string;business_state:string;process_sync_status:string;current_route_step_id:string;pending_receipt_step_id?:string;mapping?:{process_instance_id:string;process_definition_id:string;process_definition_version:number};tasks:{id:string;task_key:string;binding:Record<string,string>}[]}
const categories=[{id:'workflow-deliveries',name:'Workflow ที่ล้มเหลว'},{id:'login-notifications',name:'อีเมลที่ต้องติดตาม'},{id:'reconciliation',name:'ข้อมูลไม่ตรงกัน'},{id:'exceptions',name:'ข้อยกเว้นค้าง'},{id:'tasks',name:'งานรอดำเนินการ'},{id:'reminders',name:'บันทึกแจ้งเตือน'},{id:'audit-events',name:'ประวัติผู้ดูแล'}]
const category=ref('workflow-deliveries');const rows=ref<Row[]>([]);const cursor=ref<string|null>();const summary=ref<Summary>();const loading=ref(false);const saving=ref(false);const error=ref<unknown>();const message=ref('');const selected=ref<Row>();const reason=ref('');const engine=ref<Engine>();const scanOpen=ref(false);const scanDocument=ref('');const scanReason=ref('');const cleanupOpen=ref(false);const cleanupReason=ref('');const cleanupPreview=ref<Row>();let generation=0
const short=(value:unknown)=>value?String(value).slice(-8):'—'
const date=(value:unknown)=>value?bangkok(String(value)):'—'
const age=(value:number)=>`${Math.max(0,Math.floor(value/60))} นาที`
const alertNames:Record<string,string>={WORKFLOW_DEAD_LETTER:'Workflow พักหลังลองไม่สำเร็จ',MAIL_DELIVERY_FAILED:'อีเมลส่งไม่สำเร็จ',RECONCILIATION_MISMATCH:'ข้อมูลแอปและ Workflow ไม่ตรงกัน'}
const alertLabel=(code:string)=>alertNames[code]||code
const rowId=(row:Row)=>String(row.id||`${row.document_id}:${row.code}`)
async function load(more=false){if(!admin.value)return;const run=++generation;loading.value=true;error.value=undefined;try{const path=category.value==='reconciliation'?'/admin/operations/reconciliation/findings?state=OPEN&limit=100':`/admin/operations/${category.value}?limit=50${more&&cursor.value?`&cursor=${encodeURIComponent(cursor.value)}`:''}`;const [totals,page]=await Promise.all([api.get<Summary>('/admin/operations/summary'),api.get<Page<Row>>(path)]);if(run!==generation)return;summary.value=totals;rows.value=more?[...rows.value,...page.items]:page.items;cursor.value=page.next_cursor}catch(e){if(run===generation)error.value=e}finally{if(run===generation)loading.value=false}}
async function change(value:string){category.value=value;rows.value=[];cursor.value=null;selected.value=undefined;engine.value=undefined;await load()}
async function inspect(row:Row){if(!row.document_id)return;error.value=undefined;try{engine.value=await api.get<Engine>(`/admin/operations/documents/${row.document_id}/engine`)}catch(e){error.value=e}}
function openRetry(row:Row){selected.value=row;reason.value='';message.value=''}
async function retry(){const row=selected.value;if(!row)return;saving.value=true;error.value=undefined;try{const workflow=category.value==='workflow-deliveries';await api.command(workflow?`/admin/workflow-operations/${row.operation_id}/retry`:`/admin/login-notifications/${row.id}/retry`,{expected_version:row.version,reason:reason.value.trim(),...(workflow?{delivery_id:row.id}:{})});selected.value=undefined;message.value='เข้าคิวงานเดิมแล้ว ตรวจสถานะอีกครั้งหลังระบบประมวลผล';await load()}catch(e){error.value=e}finally{saving.value=false}}
function openScan(document?:string){scanOpen.value=true;scanDocument.value=document||'';scanReason.value='';message.value=''}
async function scan(){saving.value=true;error.value=undefined;try{const result=await api.command<{scanned:number;pending:number;mismatches:number}>('/admin/operations/reconciliation/scan',{reason:scanReason.value.trim(),limit:100,...(scanDocument.value?{document_id:scanDocument.value.trim()}:{})});scanOpen.value=false;message.value=`ตรวจเทียบ ${result.scanned} เรื่อง พบความต่าง ${result.mismatches} เรื่อง รอประสาน ${result.pending} เรื่อง`;await load()}catch(e){error.value=e}finally{saving.value=false}}
async function previewCleanup(){saving.value=true;error.value=undefined;try{cleanupPreview.value=await api.command<Row>('/admin/operations/orphan-uploads/cleanup',{dry_run:true,limit:100,reason:cleanupReason.value.trim()});message.value='ตรวจรายการรูปที่เข้าเกณฑ์แล้ว ยังไม่ได้ลบไฟล์';await load()}catch(e){error.value=e}finally{saving.value=false}}
onMounted(()=>load());onBeforeUnmount(()=>generation++)
</script>
<template>
  <div class="page-head"><div><h1>ติดตามและกู้คืนระบบ</h1><p>ตรวจงานที่ผิดพลาดและลองงานเดิมอีกครั้ง พร้อมบันทึกผู้ดำเนินการและเหตุผล</p></div><button class="button" type="button" :disabled="loading||saving" @click="load()">โหลดล่าสุด</button></div>
  <Feedback v-if="!admin" :error="new Error('เฉพาะผู้ดูแลส่วนกลางเท่านั้น')" />
  <template v-else>
    <Feedback :error="error" :message="message" />
    <section v-if="summary" class="panel" aria-label="สถานะระบบล่าสุด"><h2>งานที่ต้องติดตาม</h2><ul v-if="summary.alerts?.length" role="status" class="notice sync-notice"><li v-for="alert in summary.alerts" :key="alert.code">{{alertLabel(alert.code)}} {{alert.count}} รายการ</li></ul><div class="table-wrap"><table><thead><tr><th>ประเภทงาน</th><th>รอประมวลผล</th><th>ต้องลองใหม่ / ล้มเหลว</th><th>อายุงานเก่าสุด</th></tr></thead><tbody>
      <tr><th scope="row">Workflow</th><td>{{summary.workflow.pending}}</td><td>{{summary.workflow.retry_wait}} / {{summary.workflow.dead_letter}}</td><td>{{age(summary.workflow.oldest_pending_age_seconds)}}</td></tr>
      <tr><th scope="row">อีเมลเข้าสู่ระบบ</th><td>{{summary.mail.pending}} · กำลังส่ง {{summary.mail.processing}}</td><td>{{summary.mail.retry_wait}} / {{summary.mail.failed}}</td><td>{{age(summary.mail.oldest_pending_age_seconds)}}</td></tr>
      <tr><th scope="row">งานรอผู้ดำเนินการ</th><td>{{summary.waiting_tasks}}</td><td>—</td><td>{{age(summary.oldest_waiting_age_seconds)}}</td></tr>
    </tbody></table></div><p class="hint">ข้อมูลไม่ตรงกัน {{summary.reconciliation_open}} รายการ · ข้อยกเว้นค้าง {{summary.open_exceptions}} เรื่อง</p></section>
    <div class="view-tabs" role="group" aria-label="ประเภทงานระบบ"><button v-for="tab in categories" :key="tab.id" type="button" class="button" :data-testid="`ops-tab-${tab.id}`" :aria-pressed="category===tab.id" :disabled="saving" @click="change(tab.id)">{{tab.name}}</button></div>
    <section class="panel"><div class="actions"><button type="button" data-testid="ops-scan-open" class="button" :disabled="saving" @click="openScan()">ตรวจเทียบข้อมูลกับ Workflow</button><button type="button" class="button" :disabled="saving" @click="cleanupOpen=!cleanupOpen;cleanupPreview=undefined">ตรวจรูปที่ยังไม่ผูกหลักฐาน</button><NuxtLink class="text-link" to="/admin/notifications">ติดตามอีเมลรายผู้รับ</NuxtLink></div><UProgress v-if="loading" />
      <p v-if="category==='tasks'" class="hint">อายุงานเป็นเวลาที่รอดำเนินการ ยังไม่ได้ประเมินว่าเกิน SLA</p><p v-if="category==='exceptions'" class="hint">ข้อยกเว้นยังรอผู้มีสิทธิ์ตรวจตามขั้นตอนที่กำหนด หน้านี้ไม่ยืนยันรับหนังสือหรือเปลี่ยนเส้นทางแทนผู้ดำเนินการ</p><p v-if="category==='reminders'" class="hint">บันทึกจาก timer ใช้ติดตามงาน ไม่ได้ยืนยันรับหนังสือหรือรับรองว่าส่งแจ้งเตือนถึงผู้ใช้แล้ว</p>
      <div v-if="!rows.length&&!loading" class="empty" data-testid="ops-empty">ไม่มีรายการในหมวดนี้</div>
      <div v-if="rows.length" class="table-wrap"><table><thead><tr><th>อ้างอิง / ประเภท</th><th>สถานะ</th><th>เวลา / จำนวนครั้ง</th><th>ดำเนินการ</th></tr></thead><tbody><tr v-for="row in rows" :key="rowId(row)">
        <td><p class="break">{{row.code||row.action||row.task_key||`งาน #${short(row.id)}`}}</p><p v-if="row.document_id" class="hint break">หนังสือ #{{short(row.document_id)}}</p><p v-if="row.operation_id" class="hint break">คำสั่ง #{{short(row.operation_id)}}</p><p v-if="row.actor_id||row.opened_by" class="hint break">ผู้ดำเนินการ #{{short(row.actor_id||row.opened_by)}}</p></td>
        <td><StatusTag v-if="row.status||row.state" :value="String(row.status||row.state)" /><p v-if="row.last_error_code" class="hint">{{row.last_error_code}}</p><p v-if="row.previous_state" class="hint">{{row.previous_state}}</p><p v-if="row.age_seconds!=null" class="hint">รอ {{age(Number(row.age_seconds))}}</p></td>
        <td>{{date(row.created_at||row.opened_at||row.recorded_at||row.last_seen_at||row.login_at)}}<p v-if="row.attempts!=null||row.attempt_count!=null" class="hint">ลองแล้ว {{row.attempts??row.attempt_count}} ครั้ง</p><p v-if="row.next_retry_at" class="hint">ลองได้ {{date(row.next_retry_at)}}</p></td>
        <td><div class="actions"><button v-if="row.document_id" type="button" class="button" :disabled="saving" @click="inspect(row)">ตรวจขั้นตอน</button><button v-if="['RETRY_WAIT','DEAD_LETTER','FAILED'].includes(String(row.status))&&['workflow-deliveries','login-notifications'].includes(category)" type="button" class="button primary" :data-testid="`ops-retry-${row.id}`" :disabled="saving" @click="openRetry(row)">ลองงานเดิมอีกครั้ง</button><button v-if="category==='reconciliation'" type="button" class="button" :disabled="saving" @click="openScan(String(row.document_id))">ตรวจเทียบเรื่องนี้ใหม่</button></div></td>
      </tr></tbody></table></div><button v-if="cursor" type="button" class="button" :disabled="loading||saving" @click="load(true)">โหลดรายการเพิ่มเติม</button><p v-if="category==='reconciliation'&&rows.length===100" class="hint">แสดงไม่เกิน 100 รายการแรก ใช้เลขอ้างอิงในแบบตรวจเทียบเพื่อตรวจเรื่องที่ต้องการ</p>
    </section>
    <form v-if="selected" class="panel" @submit.prevent="retry"><h2>ลองงานเดิม #{{short(selected.id)}} อีกครั้ง</h2><p v-if="category==='workflow-deliveries'" class="hint">ลองเฉพาะรายการที่เลือกในคำสั่งเดิม เรื่องที่สำเร็จแล้วจะไม่ถูกทำซ้ำ หากข้อมูลไม่ตรงกัน ระบบจะพักไว้ให้ตรวจ</p><p v-else class="hint">SMTP อาจรับอีเมลแล้วแม้ไม่ตอบกลับ การลองใหม่อาจทำให้ผู้รับได้รับอีเมลซ้ำ</p><div class="field"><label for="ops-retry-reason">เหตุผลที่ลองอีกครั้ง</label><textarea id="ops-retry-reason" v-model="reason" data-testid="ops-retry-reason" required maxlength="1000" :disabled="saving" /></div><div class="actions"><button data-testid="ops-retry-submit" class="button primary" :disabled="saving||!reason.trim()">{{saving?'กำลังเข้าคิว…':'เข้าคิวงานเดิม'}}</button><button type="button" class="button" :disabled="saving" @click="selected=undefined">กลับ</button></div></form>
    <section v-if="engine" class="panel" data-testid="ops-engine"><h2>ขั้นตอนปัจจุบัน · #{{short(engine.document_id)}}</h2><div class="actions"><StatusTag :value="engine.business_state" /><StatusTag :value="engine.process_sync_status" /></div><p class="hint break">ขั้นเส้นทางปัจจุบัน {{engine.current_route_step_id}}</p><p v-if="engine.pending_receipt_step_id" class="hint break">ขั้นรอยืนยันรับ {{engine.pending_receipt_step_id}}</p><p v-if="engine.mapping" class="hint break">Workflow เวอร์ชัน {{engine.mapping.process_definition_version}} · {{engine.mapping.process_instance_id}}</p><ul><li v-for="task in engine.tasks" :key="task.id" class="break">{{task.task_key}} · {{task.id}}<p v-for="(value,key) in task.binding" :key="key" class="hint break">{{key}}: {{value}}</p></li></ul><p v-if="!engine.tasks.length" class="hint">ไม่มี task ที่เปิดอยู่ ตรวจผล reconciliation ประกอบกับสถานะหนังสือ</p><button type="button" class="button actions" @click="openScan(engine.document_id)">ตรวจเทียบเรื่องนี้</button></section>
    <form v-if="scanOpen" class="panel" @submit.prevent="scan"><h2>ตรวจเทียบข้อมูลกับ Workflow</h2><p class="hint">อ่านสถานะและบันทึกสิ่งที่ไม่ตรงกัน ไม่เลื่อนขั้นตอนหรือสร้างหลักฐานรับหนังสือ</p><div class="field"><label for="ops-scan-document">เลขอ้างอิงหนังสือ UUID (เว้นว่างเพื่อตรวจ 100 เรื่องแรก)</label><input id="ops-scan-document" v-model="scanDocument" :disabled="saving" /></div><div class="field"><label for="ops-scan-reason">เหตุผลที่ตรวจเทียบ</label><textarea id="ops-scan-reason" v-model="scanReason" data-testid="ops-scan-reason" required maxlength="1000" :disabled="saving" /></div><div class="actions"><button data-testid="ops-scan-submit" class="button primary" :disabled="saving||!scanReason.trim()">{{saving?'กำลังตรวจ…':'ตรวจเทียบ'}}</button><button type="button" class="button" :disabled="saving" @click="scanOpen=false">กลับ</button></div></form>
    <form v-if="cleanupOpen" class="panel" @submit.prevent="previewCleanup"><h2>ตรวจรูปที่ยังไม่ผูกหลักฐาน</h2><p class="hint">ตรวจได้เมื่อกำหนดอายุรูปตามนโยบายแล้ว รูปที่ยืนยันหรือผูกหลักฐานจะไม่ถูกเลือก ผลตรวจนี้ยังไม่ลบไฟล์</p><div class="field"><label for="ops-cleanup-reason">เหตุผลที่ตรวจรูป</label><textarea id="ops-cleanup-reason" v-model="cleanupReason" required maxlength="1000" :disabled="saving" /></div><div v-if="cleanupPreview" role="status">เข้าเกณฑ์ {{cleanupPreview.candidates}} รูป · ล้มเหลว {{cleanupPreview.failed||0}} รายการ</div><div class="actions"><button class="button" :disabled="saving||!cleanupReason.trim()">{{saving?'กำลังตรวจ…':'ตรวจรายการโดยไม่ลบ'}}</button><button type="button" class="button" :disabled="saving" @click="cleanupOpen=false">กลับ</button></div></form>
  </template>
</template>

<style scoped>
table{min-width:740px}td .actions{min-width:210px}td .button{white-space:nowrap}
</style>
